update tattoo_lessons
set content = replace(content, $fix2a$مقیاس فیتزپاتریک (Fitzpatrick) پوست را از خیلی روشن تا خیلی تیره، حدود تیپ یک تا شش، بر اساس واکنش به آفتاب دسته‌بندی می‌کند. این مقیاس تشخیص بیماری نیست. برای تاتو فقط یک هشدار کاربردی دارد: هرچه رنگ‌دانهٔ خود پوست بیشتر باشد، رنگ روشن تاتو کمتر از زمینه جدا دیده می‌شود.$fix2a$, $fix2b$یک دسته‌بندی معروف پوست، پوست را از خیلی روشن تا خیلی تیره به شش گروه تقسیم می‌کند، بر اساس این‌که در آفتاب می‌سوزد یا تیره می‌شود. این دسته‌بندی تشخیص بیماری نیست. برای تاتو فقط یک هشدار دارد: هرچه رنگ خود پوست بیشتر باشد، رنگ روشن تاتو کمتر از زمینه جدا دیده می‌شود.$fix2b$), updated_at = now()
